dead_letters = []


def send(record):
    if "@" not in record["email"]:
        raise ValueError("bad email")
    print("sent", record["id"])


def process(records):
    for r in records:
        send(r)


process([{"id": 1, "email": "a@x"}, {"id": 2, "email": "b@x"}, {"id": 3, "email": "bad"}, {"id": 4, "email": "d@x"}])
